7	import { join } from 'node:path';
8	import { writeFileSync } from 'node:fs';
9	import os from 'node:os';
10	import {
11	  type SandboxManager,
12	  type SandboxRequest,
13	  type SandboxedCommand,
14	} from '../../services/sandboxManager.js';
15	import {
16	  sanitizeEnvironment,
17	  getSecureSanitizationConfig,
18	  type EnvironmentSanitizationConfig,
19	} from '../../services/environmentSanitization.js';
20	
21	let cachedBpfPath: string | undefined;
22	
23	function getSeccompBpfPath(): string {
24	  if (cachedBpfPath) return cachedBpfPath;
25	
26	  const arch = os.arch();
27	  let AUDIT_ARCH: number;
28	  let SYS_ptrace: number;
29	
30	  if (arch === 'x64') {
31	    AUDIT_ARCH = 0xc000003e; // AUDIT_ARCH_X86_64
32	    SYS_ptrace = 101;
33	  } else if (arch === 'arm64') {
34	    AUDIT_ARCH = 0xc00000b7; // AUDIT_ARCH_AARCH64
35	    SYS_ptrace = 117;
36	  } else if (arch === 'arm') {
37	    AUDIT_ARCH = 0x40000028; // AUDIT_ARCH_ARM
38	    SYS_ptrace = 26;
39	  } else if (arch === 'ia32') {
40	    AUDIT_ARCH = 0x40000003; // AUDIT_ARCH_I386
41	    SYS_ptrace = 26;
42	  } else {
43	    throw new Error(`Unsupported architecture for seccomp filter: ${arch}`);
44	  }
45	
46	  const EPERM = 1;
47	  const SECCOMP_RET_KILL_PROCESS = 0x80000000;
48	  const SECCOMP_RET_ERRNO = 0x00050000;
49	  const SECCOMP_RET_ALLOW = 0x7fff0000;
50	
51	  const instructions = [
52	    { code: 0x20, jt: 0, jf: 0, k: 4 }, // Load arch
53	    { code: 0x15, jt: 1, jf: 0, k: AUDIT_ARCH }, // Jump to kill if arch != native arch
54	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_KILL_PROCESS }, // Kill
55	
56	    { code: 0x20, jt: 0, jf: 0, k: 0 }, // Load nr
57	    { code: 0x15, jt: 0, jf: 1, k: SYS_ptrace }, // If ptrace, jump to ERRNO
58	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_ERRNO | EPERM }, // ERRNO
59	
60	    { code: 0x06, jt: 0, jf: 0, k: SECCOMP_RET_ALLOW }, // Allow
61	  ];
62	
63	  const buf = Buffer.alloc(8 * instructions.length);
64	  for (let i = 0; i < instructions.length; i++) {
65	    const inst = instructions[i];
66	    const offset = i * 8;
67	    buf.writeUInt16LE(inst.code, offset);
68	    buf.writeUInt8(inst.jt, offset + 2);
69	    buf.writeUInt8(inst.jf, offset + 3);
70	    buf.writeUInt32LE(inst.k, offset + 4);
71	  }
72	
73	  const bpfPath = join(os.tmpdir(), `gemini-cli-seccomp-${process.pid}.bpf`);
74	  writeFileSync(bpfPath, buf);
75	  cachedBpfPath = bpfPath;
76	  return bpfPath;
77	}
78	
79	/**
80	 * Options for configuring the LinuxSandboxManager.
81	 */
82	export interface LinuxSandboxOptions {
83	  /** The primary workspace path to bind into the sandbox. */
84	  workspace: string;
85	  /** Additional paths to bind into the sandbox. */
86	  allowedPaths?: string[];
87	  /** Optional base sanitization config. */
88	  sanitizationConfig?: EnvironmentSanitizationConfig;
89	}
90	
91	/**
92	 * A SandboxManager implementation for Linux that uses Bubblewrap (bwrap).
93	 */
94	export class LinuxSandboxManager implements SandboxManager {
95	  constructor(private readonly options: LinuxSandboxOptions) {}
96	
97	  async prepareCommand(req: SandboxRequest): Promise<SandboxedCommand> {
98	    const sanitizationConfig = getSecureSanitizationConfig(
99	      req.config?.sanitizationConfig,
100	      this.options.sanitizationConfig,
101	    );
102	
103	    const sanitizedEnv = sanitizeEnvironment(req.env, sanitizationConfig);
104	
105	    const bwrapArgs: string[] = [
106	      '--unshare-all',
107	      '--new-session', // Isolate session
108	      '--die-with-parent', // Prevent orphaned runaway processes
109	      '--ro-bind',
110	      '/',
111	      '/',
112	      '--dev', // Creates a safe, minimal /dev (replaces --dev-bind)
113	      '/dev',
114	      '--proc', // Creates a fresh procfs for the unshared PID namespace
115	      '/proc',
116	      '--tmpfs', // Provides an isolated, writable /tmp directory
117	      '/tmp',
118	      // Note: --dev /dev sets up /dev/pts automatically
119	      '--bind',
120	      this.options.workspace,
121	      this.options.workspace,
122	    ];
123	
124	    const allowedPaths = this.options.allowedPaths ?? [];
125	    for (const path of allowedPaths) {
126	      if (path !== this.options.workspace) {
127	        bwrapArgs.push('--bind', path, path);
128	      }
129	    }
130	
131	    const bpfPath = getSeccompBpfPath();
132	
133	    bwrapArgs.push('--seccomp', '9');
134	    bwrapArgs.push('--', req.command, ...req.args);
135	
136	    const shArgs = [
137	      '-c',
138	      'bpf_path="$1"; shift; exec bwrap "$@" 9< "$bpf_path"',
139	      '_',
140	      bpfPath,
141	      ...bwrapArgs,
142	    ];
143	
144	    return {
145	      program: 'sh',
146	      args: shArgs,
147	      env: sanitizedEnv,
148	    };
149	  }
150	}
