18	/**
19	 * A simple asynchronous wrapper for execFile that returns the exit status,
20	 * stdout, and stderr. Unlike spawnSync, this does not block the Node.js
21	 * event loop, allowing the local HTTP test server to function.
22	 */
23	async function runCommand(command: SandboxedCommand) {
24	  try {
25	    const { stdout, stderr } = await promisify(execFile)(
26	      command.program,
27	      command.args,
28	      {
29	        cwd: command.cwd,
30	        env: command.env,
31	        encoding: 'utf-8',
32	      },
33	    );
34	    return { status: 0, stdout, stderr };
35	  } catch (error: unknown) {
36	    const err = error as {
37	      code?: number;
38	      stdout?: string;
39	      stderr?: string;
40	    };
41	    return {
42	      status: err.code ?? 1,
43	      stdout: err.stdout ?? '',
44	      stderr: err.stderr ?? '',
45	    };
46	  }
47	}
