93	    describe('File System Access', () => {
94	      it('should block file system access outside the workspace', async () => {
95	        const manager = new MacOsSandboxManager({ workspace: process.cwd() });
96	        const blockedPath = '/Users/Shared/.gemini_test_sandbox_blocked';
